insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_GTE_15","title":"¿Habrá 15 o más carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":15},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_LTE_5","title":"¿El partido se queda en 5 carreras o menos?","description":"Se corrige con el marcador final.","category":"total","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":5},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_LTE_6","title":"¿Habrá 6 o menos carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":6},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_LTE_7","title":"¿Habrá 7 o menos carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":7},"priority":0,"cooldown":2,"tags":["total"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;